"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5610],{35427:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TrainShieldController","desc":"Discovers shield-console instances via CollectionService tags and wires their\\nProximityPrompt to send `ReqRechargeShield` (mirroring TrainClient\'s refuel\\nprompt, including the \\"hold with no energy\\" early-out). On a successful\\nrecharge it plays a SoundManager SFX. Incoming `TrainShieldSync` packets are\\nbridged into `Signals.OnTrainShieldChanged` so the HUD controller never\\ntouches the network layer directly.","realm":["Client"],"source":{"line":14,"path":"src/StarterPlayer/StarterPlayerScripts/TrainShieldController.client.luau"}}')}}]);